import React, { Component } from "react";
import About from "./CustomComponents/about";
import MyCar from "./CustomComponents/MyCar";
import Car from "./CustomComponents/car";
import Schedule from "./CustomComponents/schedule";
import Rating from "./CustomComponents/Rating";
import ServiceProvider from "./CustomComponents/serviceProvider";
import Expense from "./CustomComponents/expense";
import Task from "./CustomComponents/task";
import Notification from "./CustomComponents/notification";
import SignupView from "./CustomComponents/SignupView";
import LoginView from "./CustomComponents/LoginView";
import axios from "axios";
import { API_URL } from "./Utils/Configuration";

class App extends Component {
  constructor(props) {
    super(props);
    this.state = {
      CurrentPage: 'ABOUT',
      user: null,
      sessionChecked: false
    };
  }

  componentDidMount() {
    this.checkSession();
  }

  checkSession = async () => {
    try {
      const response = await axios.get(`${API_URL}/users/session`, { withCredentials: true });
      if (response.data.logged_in) {
        this.setState({ user: response.data.user, sessionChecked: true });
      } else {
        this.setState({ sessionChecked: true });
      }
    } catch (error) {
      console.error("Error checking session:", error);
      this.setState({ sessionChecked: true });
    }
  };

  handleLogout = async () => {
    try {
      await axios.get(`${API_URL}/users/logout`, { withCredentials: true });
    } catch (err) {
      console.error("Logout error:", err);
    } finally {
      this.setState({ user: null, CurrentPage: 'ABOUT' });
    }
  };

  QSetLoggedIn = (user) => {
    this.setState({ user, CurrentPage: 'CAR' });
  };

  QSetView = (obj) => {
    this.setState({ CurrentPage: obj.page });
  };

  QGetView() {
    const { CurrentPage, user, sessionChecked } = this.state;

    if (!sessionChecked) {
      return (
        <div style={{
          minHeight: "80vh", display: "flex", alignItems: "center",
          justifyContent: "center", color: "#555", fontSize: 14,
          fontFamily: "'DM Sans', system-ui, sans-serif"
        }}>
          <div style={{ textAlign: "center" }}>
            <div style={{
              fontFamily: "'Bebas Neue', sans-serif", fontSize: 32,
              letterSpacing: ".1em", color: "#e0a820", marginBottom: 12
            }}>CARCARE</div>
            <div>Loading…</div>
          </div>
        </div>
      );
    }

    const protectedPages = ['CAR', 'MY_CAR', 'RATING', 'SCHEDULE', 'SERVICEPROVIDER', 'EXPENSE', 'TASK', 'NOTIFICATION'];
    if (protectedPages.includes(CurrentPage) && !user) {
      return <LoginView QUserFromChild={this.QSetLoggedIn} />;
    }

    switch (CurrentPage) {
      case 'CAR':             return <Car />;
      case 'MY_CAR':          return <MyCar />;
      case 'RATING':          return <Rating />;
      case 'SCHEDULE':        return <Schedule />;
      case 'SERVICEPROVIDER': return <ServiceProvider />;
      case 'EXPENSE':         return <Expense />;
      case 'TASK':            return <Task />;
      case 'NOTIFICATION':    return <Notification />;
      case 'SIGNUP':          return <SignupView QUserFromChild={this.QSetLoggedIn} />;
      case 'LOGIN':           return <LoginView QUserFromChild={this.QSetLoggedIn} />;
      default:                return <About />;
    }
  }

  render() {
    const { user } = this.state;
    return (
      <div id="APP" style={{ background: "#0d0f12", minHeight: "100vh", fontFamily: "'DM Sans', system-ui, sans-serif" }}>
        <style>{`@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Bebas+Neue&display=swap');`}</style>
        <nav style={{
          backgroundColor: '#0d0f12', borderBottom: "1px solid #252830",
          padding: "0 24px", display: "flex", alignItems: "center",
          height: 56, position: "sticky", top: 0, zIndex: 100
        }}>
          <a onClick={() => this.QSetView({ page: 'ABOUT' })} href="#" style={{
            fontFamily: "'Bebas Neue', sans-serif", fontSize: 24,
            letterSpacing: ".1em", color: "#e0a820", textDecoration: "none", marginRight: 32
          }}>
            CARCARE
          </a>
          <div style={{ display: "flex", gap: 4, flex: 1 }}>
            {user ? (
              <>
                <NavLink onClick={() => this.QSetView({ page: 'CAR' })}>Car</NavLink>
                <NavLink onClick={() => this.QSetView({ page: 'MY_CAR' })}>My Car</NavLink>
                <NavLink onClick={() => this.QSetView({ page: 'RATING' })}>Rating</NavLink>
                <NavLink onClick={this.handleLogout} danger>Log out</NavLink>
              </>
            ) : (
              <>
                <NavLink onClick={() => this.QSetView({ page: 'SIGNUP' })}>Sign up</NavLink>
                <NavLink onClick={() => this.QSetView({ page: 'LOGIN' })}>Log in</NavLink>
              </>
            )}
          </div>
        </nav>
        <div id="viewer">{this.QGetView()}</div>
      </div>
    );
  }
}

function NavLink({ onClick, children, danger }) {
  return (
    <a onClick={onClick} href="#" style={{
      color: danger ? "#E24B4A" : "#888", textDecoration: "none",
      fontSize: 13, fontWeight: 500, padding: "6px 12px", borderRadius: 8
    }}
      onMouseEnter={e => e.target.style.color = danger ? "#ff6b6b" : "#f0f0f0"}
      onMouseLeave={e => e.target.style.color = danger ? "#E24B4A" : "#888"}
    >
      {children}
    </a>
  );
}

export default App;