import React, { useEffect } from "react";
import axios from "axios";
import { API_URL } from "../Utils/Configuration";

const LogOutView = ({ onLogoutSuccess }) => {
  useEffect(() => {
    const logOut = async () => {
      try {
        await axios.get(`${API_URL}/users/logout`, { withCredentials: true });
      } catch (err) {
        console.error("Logout error:", err);
      } finally {
        // Always redirect regardless of server response
        if (onLogoutSuccess) onLogoutSuccess();
      }
    };
    logOut();
  }, [onLogoutSuccess]);

  return (
    <div style={S.page}>
      <style>{FONTS}</style>
      <div style={S.card}>
        <div style={S.logo}>CARCARE</div>
        <div style={S.subtitle}>Signing you out…</div>
        <div style={S.spinner}>
          <div style={S.dot} />
          <div style={{ ...S.dot, animationDelay: ".2s" }} />
          <div style={{ ...S.dot, animationDelay: ".4s" }} />
        </div>
      </div>
      <style>{`
        @keyframes bounce {
          0%, 80%, 100% { transform: scale(0); opacity: .3; }
          40% { transform: scale(1); opacity: 1; }
        }
      `}</style>
    </div>
  );
};

const FONTS = `@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Bebas+Neue&display=swap');*{box-sizing:border-box;}`;

const S = {
  page: {
    minHeight: "100vh", width: "100%", background: "#0d0f12",
    display: "flex", alignItems: "center", justifyContent: "center",
    fontFamily: "'DM Sans', system-ui, sans-serif", padding: "20px"
  },
  card: {
    width: "100%", maxWidth: 420, background: "#16181e",
    border: "1px solid #252830", borderRadius: 20, padding: "48px 36px",
    boxShadow: "0 24px 80px rgba(0,0,0,.5)", textAlign: "center"
  },
  logo: {
    fontFamily: "'Bebas Neue', sans-serif", fontSize: 36,
    letterSpacing: ".1em", color: "#e0a820", marginBottom: 8
  },
  subtitle: { fontSize: 14, color: "#555", marginBottom: 32 },
  spinner: { display: "flex", justifyContent: "center", gap: 8 },
  dot: {
    width: 10, height: 10, borderRadius: "50%", background: "#e0a820",
    animation: "bounce 1.4s infinite ease-in-out"
  }
};

export default LogOutView;